<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Certificate | Jerin's Coaching</title><style>*{box-sizing:border-box}body{margin:0;padding:28px;background:#f4f7fb;font-family:Georgia,serif;color:#102b4e}.certificate{max-width:1000px;margin:auto;background:#fff;border:12px solid #12345a;outline:2px solid #f3c95d;outline-offset:-22px;padding:60px 44px;text-align:center;min-height:650px;display:flex;flex-direction:column;justify-content:center}.brand{font:700 22px Arial}.brand span{color:#ef2d83}.eyebrow{font:700 13px Arial;letter-spacing:4px;color:#d19a18;margin-top:35px}.title{font-size:48px;margin:15px 0}.line{width:150px;height:3px;background:#f3c95d;margin:16px auto}.name{font-size:36px;color:#e92c80;border-bottom:1px solid #d7dfeb;padding:8px 15px;display:inline-block}.course{font-size:25px;margin:18px 0}.meta{font:14px Arial;color:#56657a;margin-top:25px}.number{font:700 14px Arial;letter-spacing:1px;margin-top:12px}.actions{max-width:1000px;margin:16px auto;text-align:right}.actions button,.actions a{background:#12345a;color:white;padding:11px 16px;border:0;border-radius:8px;text-decoration:none;cursor:pointer}@media print{body{padding:0;background:white}.certificate{max-width:none;min-height:100vh}.actions{display:none}}@media(max-width:600px){.certificate{padding:50px 20px;min-height:560px}.title{font-size:34px}.name{font-size:26px}.course{font-size:20px}}</style></head><body><div class="actions"><a href="{{ route('student.certificates.index') }}">My certificates</a> <button onclick="window.print()">Print / Save PDF</button></div><main class="certificate"><div class="brand">Jerin's <span>Coaching</span></div><div class="eyebrow">LEARN WITHOUT FEAR</div><h1 class="title">Certificate of Completion</h1><div class="line"></div><p>This certificate is proudly presented to</p><div class="name">{{ $certificate->user->name }}</div><p>for successfully completing the course</p><div class="course">{{ $certificate->course->title }}</div><p>We celebrate your dedication to learning and growth.</p><div class="meta">Issued {{ $certificate->issued_at->format('d F Y') }}</div><div class="number">VERIFICATION ID: {{ $certificate->certificate_number }}</div><div class="meta">Verify at: {{ route('certificates.verify',$certificate->certificate_number) }}</div></main></body></html>
